    private int calculateage() {
        if (this.binding.CorrectDobageET.getText().toString().isEmpty()) {
            return 0;
        }
        LocalDate localDate = LocalDate.parse(new SimpleDateFormat("yyyy-MM-dd").format(new Date(this.binding.CorrectDobageET.getText().toString())));
        LocalDate localDateNow = LocalDate.now();
        if (localDate == null || localDateNow == null) {
            return 0;
        }
        return Period.between(localDate, localDateNow).getYears();
    }

