    private void openFragment(Fragment fragment, String selectedFragment) {
        Bundle bundle = new Bundle();
        bundle.putSerializable("FinalMap", this.submitMap);
        bundle.putString("Epicnumber", this.binding.epicNumberET.getText().toString());
        bundle.putString("Referenceno", this.referenceNumber);
        bundle.putString("Draftname", this.binding.nameApplicantET.getText().toString());
        bundle.putString("Draftcreatedon", this.draftdate);
        fragment.setArguments(bundle);
        FragmentTransaction fragmentTransactionBeginTransaction = requireActivity().getSupportFragmentManager().beginTransaction();
        fragmentTransactionBeginTransaction.replace(R.id.frame_forms_migration, fragment, selectedFragment);
        fragmentTransactionBeginTransaction.addToBackStack(fragment.getClass().getName());
        fragmentTransactionBeginTransaction.setTransition(4099);
        fragmentTransactionBeginTransaction.commitAllowingStateLoss();
    }

    private void openFragment1(Fragment fragment, String selectedFragment) {
        this.bundle1.putString("Correction", "Y");
        this.bundle1.putString("epicDetails", this.epicDetails);
        this.bundle1.putString("FlagKey", "0");
        fragment.setArguments(this.bundle1);
        FragmentTransaction fragmentTransactionBeginTransaction = requireActivity().getSupportFragmentManager().beginTransaction();
        fragmentTransactionBeginTransaction.replace(R.id.frame_voter_forms, fragment, selectedFragment);
        fragmentTransactionBeginTransaction.addToBackStack(fragment.getClass().getName());
        fragmentTransactionBeginTransaction.setTransition(4099);
        fragmentTransactionBeginTransaction.commitAllowingStateLoss();
    }

