    /* JADX INFO: Access modifiers changed from: private */
    public String convertDOB(String dob) {
        try {
            return new SimpleDateFormat(DDMMYY).format(new SimpleDateFormat("yyyy-MM-dd").parse(dob));
        } catch (Exception e) {
            Log.e("DateException", e.toString());
            return null;
        }
    }

    /* JADX INFO: Access modifiers changed from: private */
    public String DOBClaculator(int age) {
        Calendar calendar = Calendar.getInstance();
        calendar.add(1, -age);
        return new SimpleDateFormat(DDMMYY).format(calendar.getTime());
    }

    public static Calendar calculateDobFromAge(int age) {
        Calendar calendar = Calendar.getInstance();
        int i = calendar.get(1) - age;
        Calendar calendar2 = Calendar.getInstance();
        calendar2.set(1, i);
        if (calendar.get(2) < calendar2.get(2) || (calendar.get(2) == calendar2.get(2) && calendar.get(5) < calendar2.get(5))) {
            calendar2.add(1, -1);
        }
        calendar2.set(2, calendar.get(2));
        calendar2.set(5, calendar.get(5));
        return calendar2;
    }

